{
  "ordinary_at_deadline": true,
  "correction_window": {
    "amount": 1,
    "unit": "hours"
  },
  "correction_at_window_end": false,
  "correction_scope": "before_start",
  "reasons": {
    "R1": "일반 취소 마감은 이용 시작 24시간 전입니다. 이는 until_start_seconds가 86400초(24시간) 이상일 때 허용됩니다. 마감 시점(24시간 전)은 허용됩니다.",
    "R2": "이용이 시작되면 일반 취소는 마감됩니다. until_start_seconds가 0 이하일 때는 취소가 불가능합니다. 시작 시점(0초)은 허용되지 않습니다.",
    "R3": "방금 잘못 예약한 고객에게는 별도의 정정 시간이 있습니다. '방금'이라는 표현은 1시간 이내로 해석하며, 이 기간은 예약 생성 후 경과한 시간(age_seconds)이 1시간 이하일 때 허용됩니다. 정정 기간은 이용 시작 전에만 적용됩니다."
  }
}
